// server/src/services/company-export-readme.ts
var ROLE_LABELS = {
  ceo: "CEO",
  cto: "CTO",
  cmo: "CMO",
  cfo: "CFO",
  coo: "COO",
  vp: "VP",
  manager: "Manager",
  engineer: "Engineer",
  agent: "Agent"
};
function skillSourceLabel(skill) {
  if (skill.sourceLocator) {
    if (skill.sourceType === "github" || skill.sourceType === "skills_sh" || skill.sourceType === "url") {
      return `[${skill.sourceType}](${skill.sourceLocator})`;
    }
    return skill.sourceLocator;
  }
  if (skill.sourceType === "local") return "local";
  return skill.sourceType ?? "\u2014";
}
function generateReadme(manifest, options) {
  const lines = [];
  lines.push(`# ${options.companyName}`);
  lines.push("");
  if (options.companyDescription) {
    lines.push(`> ${options.companyDescription}`);
    lines.push("");
  }
  if (manifest.agents.length > 0) {
    lines.push("![Org Chart](images/org-chart.png)");
    lines.push("");
  }
  lines.push("## What's Inside");
  lines.push("");
  lines.push("> This is an [Agent Company](https://agentcompanies.io) package from [Taskcore](https://taskcore.khulnasoft.com)");
  lines.push("");
  const counts = [];
  if (manifest.agents.length > 0) counts.push(["Agents", manifest.agents.length]);
  if (manifest.projects.length > 0) counts.push(["Projects", manifest.projects.length]);
  if (manifest.skills.length > 0) counts.push(["Skills", manifest.skills.length]);
  if (manifest.issues.length > 0) counts.push(["Tasks", manifest.issues.length]);
  if (counts.length > 0) {
    lines.push("| Content | Count |");
    lines.push("|---------|-------|");
    for (const [label, count2] of counts) {
      lines.push(`| ${label} | ${count2} |`);
    }
    lines.push("");
  }
  if (manifest.agents.length > 0) {
    lines.push("### Agents");
    lines.push("");
    lines.push("| Agent | Role | Reports To |");
    lines.push("|-------|------|------------|");
    for (const agent of manifest.agents) {
      const roleLabel = ROLE_LABELS[agent.role] ?? agent.role;
      const reportsTo = agent.reportsToSlug ?? "\u2014";
      lines.push(`| ${agent.name} | ${roleLabel} | ${reportsTo} |`);
    }
    lines.push("");
  }
  if (manifest.projects.length > 0) {
    lines.push("### Projects");
    lines.push("");
    for (const project of manifest.projects) {
      const desc3 = project.description ? ` \u2014 ${project.description}` : "";
      lines.push(`- **${project.name}**${desc3}`);
    }
    lines.push("");
  }
  if (manifest.skills.length > 0) {
    lines.push("### Skills");
    lines.push("");
    lines.push("| Skill | Description | Source |");
    lines.push("|-------|-------------|--------|");
    for (const skill of manifest.skills) {
      const desc3 = skill.description ?? "\u2014";
      const source = skillSourceLabel(skill);
      lines.push(`| ${skill.name} | ${desc3} | ${source} |`);
    }
    lines.push("");
  }
  lines.push("## Getting Started");
  lines.push("");
  lines.push("```bash");
  lines.push("pnpm taskcore company import this-github-url-or-folder");
  lines.push("```");
  lines.push("");
  lines.push("See [Taskcore](https://taskcore.khulnasoft.com) for more information.");
  lines.push("");
  lines.push("---");
  lines.push(`Exported from [Taskcore](https://taskcore.khulnasoft.com) on ${(/* @__PURE__ */ new Date()).toISOString().split("T")[0]}`);
  lines.push("");
  return lines.join("\n");
}

