  router2.get("/companies/:companyId/live-runs", async (req, res) => {
    const companyId = req.params.companyId;
    assertCompanyAccess(req, companyId);
    const minCountParam = req.query.minCount;
    const minCount = minCountParam ? Math.max(0, Math.min(20, parseInt(minCountParam, 10) || 0)) : 0;
    const columns = {
      id: heartbeatRuns.id,
      status: heartbeatRuns.status,
      invocationSource: heartbeatRuns.invocationSource,
      triggerDetail: heartbeatRuns.triggerDetail,
      startedAt: heartbeatRuns.startedAt,
      finishedAt: heartbeatRuns.finishedAt,
      createdAt: heartbeatRuns.createdAt,
      agentId: heartbeatRuns.agentId,
      agentName: agents.name,
      adapterType: agents.adapterType,
      issueId: sql`${heartbeatRuns.contextSnapshot} ->> 'issueId'`.as("issueId")
    };
    const liveRuns = await db.select(columns).from(heartbeatRuns).innerJoin(agents, eq(heartbeatRuns.agentId, agents.id)).where(
      and(
        eq(heartbeatRuns.companyId, companyId),
        inArray(heartbeatRuns.status, ["queued", "running"])
      )
    ).orderBy(desc(heartbeatRuns.createdAt));
    if (minCount > 0 && liveRuns.length < minCount) {
      const activeIds = liveRuns.map((r5) => r5.id);
      const recentRuns = await db.select(columns).from(heartbeatRuns).innerJoin(agents, eq(heartbeatRuns.agentId, agents.id)).where(
        and(
          eq(heartbeatRuns.companyId, companyId),
          not(inArray(heartbeatRuns.status, ["queued", "running"])),
          ...activeIds.length > 0 ? [not(inArray(heartbeatRuns.id, activeIds))] : []
        )
      ).orderBy(desc(heartbeatRuns.createdAt)).limit(minCount - liveRuns.length);
      res.json([...liveRuns, ...recentRuns]);
      return;
    }
    res.json(liveRuns);
  });
